// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.StringReader;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.evaluation.ModelTripleSource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.TripleSource;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.spin.SpinParser;
import org.junit.jupiter.api.Test;

class SpinTupleFunctionAsFunctionParserTest {

	private static final String MAGIC_PROPERTIES = String.join("\n",
			"@prefix spin: <http://spinrdf.org/spin#> .",
			"@prefix sp: <http://spinrdf.org/sp#> .",
			"<urn:test:magic:random> a spin:MagicProperty ;",
			"  spin:body [ a sp:Select ; sp:text \"SELECT ?r WHERE { BIND(RAND() AS ?r) }\" ] .",
			"<urn:test:magic:upper> a spin:MagicProperty ;",
			"  spin:body [ a sp:Select ; sp:text \"SELECT ?r WHERE { BIND(UCASE(STR(?arg1)) AS ?r) }\" ] .");

	@Test
	void magicPropertyWithVolatileBodyIsVolatile() throws Exception {
		assertThat(parse("urn:test:magic:random").mustReturnDifferentResult()).isTrue();
	}

	@Test
	void magicPropertyWithDeterministicBodyIsRepeatable() throws Exception {
		assertThat(parse("urn:test:magic:upper").mustReturnDifferentResult()).isFalse();
	}

	private static Function parse(String iri) throws Exception {
		Model model = Rio.parse(new StringReader(MAGIC_PROPERTIES), RDFFormat.TURTLE);
		TripleSource store = new ModelTripleSource(model);
		IRI function = SimpleValueFactory.getInstance().createIRI(iri);

		return new SpinTupleFunctionAsFunctionParser(new SpinParser()).parse(function, store);
	}
}
